+        ],
+        correctAnswers: ["Python", "Rust"]
+      },
+      {
+        id: "q2",
+        title: "Which languages are commonly used for styling or structuring web pages?",
+        choices: [
+          { id: "q2-css", label: "CSS", detail: "Used to style layouts, typography, color, and motion." },
