      title.textContent = choice.label;

      const detail = document.createElement("span");
      detail.className = "choice__detail";
      detail.textContent = choice.detail;

      text.append(title, detail);
      label.append(input, text);
      return label;
    }

    function QuizQuestion(question) {
      const wrapper = document.createElement("div");
      wrapper.className = "form-field";

      const fieldset = document.createElement("fieldset");
      if (question.helpText) {
        fieldset.setAttribute("aria-describedby", question.id + "-help");
      }

      const legend = document.createElement("legend");
      legend.textContent = question.title;
      fieldset.appendChild(legend);

      if (question.helpText) {
        const help = document.createElement("p");
        help.className = "help-text";
        help.id = question.id + "-help";
        help.textContent = question.helpText;
        fieldset.appendChild(help);
      }

      const choices = document.createElement("div");
      choices.className = "choices";
      question.choices.forEach((choice) => {
        choices.appendChild(CheckboxOption(choice, question.id));
      });

      fieldset.appendChild(choices);
      wrapper.appendChild(fieldset);
      return wrapper;
    }

    function App() {
      const shell = document.createElement("div");
      shell.className = "page-shell";

      const hero = document.createElement("header");
      hero.className = "hero";
      hero.innerHTML = `
        <span class="eyebrow">Language Lab</span>
        <h1>Test your computer language instincts</h1>
        <p>A short multi-select quiz with a polished, product-style layout. Each question can have more than one correct answer.</p>
      `;

      const card = document.createElement("section");
      card.className = "quiz-card";
      card.setAttribute("aria-labelledby", "quiz-title");

      const cardHeader = document.createElement("div");
      cardHeader.className = "quiz-card__header";
      cardHeader.innerHTML = `
        <h2 id="quiz-title">3-question quiz</h2>
        <div class="quiz-meta">
          <span>4 answer choices per question</span>
          <span>Select multiple answers where appropriate</span>
        </div>
      `;

      const cardBody = document.createElement("div");
      cardBody.className = "quiz-card__body";

      const form = document.createElement("form");
      form.noValidate = true;
      form.setAttribute("aria-describedby", "result-status");

      quizQuestions.forEach((question) => {
        form.appendChild(QuizQuestion(question));
      });

      const footer = document.createElement("div");
      footer.className = "quiz-card__footer";

      const actions = document.createElement("div");
      actions.className = "actions";

      const button = document.createElement("button");
      button.type = "submit";
      button.className = "button";
      button.textContent = "Submit quiz";

      const result = document.createElement("div");
      result.className = "result";
      result.id = "result-status";
      result.setAttribute("aria-live", "polite");

      const panel = document.createElement("div");
      panel.className = "result-panel";
      panel.hidden = true;

      actions.append(button, result);
      footer.append(actions, panel);

      form.addEventListener("submit", (event) => {
        event.preventDefault();

        let score = 0;
        const summaryItems = [];

        quizQuestions.forEach((question) => {
          const selected = Array.from(form.querySelectorAll(`input[name="${question.id}"]:checked`))
            .map((input) => input.value)
            .sort();
          const correct = [...question.correctAnswers].sort();

          if (arraysMatch(selected, correct)) {
            score += 1;
          }

          summaryItems.push(
            `<li><strong>${question.title}</strong> &mdash; You chose ${selected.length ? selected.join(", ") : "nothing"}.</li>`
          );
        });

        result.textContent = `You scored ${score} out of ${quizQuestions.length}.`;
        panel.hidden = false;
        panel.innerHTML = `
          <h3>Quiz summary</h3>
          <p>Your selections have been recorded.</p>
          <ul>${summaryItems.join("")}</ul>
        `;
      });

      form.appendChild(footer);
      cardBody.appendChild(form);
      card.append(cardHeader, cardBody);
      shell.append(hero, card);
      return shell;
    }

    document.getElementById("app").appendChild(App());
  </script>
</body>
</html>
