337.       },
338.       {
339.         id: "q2",
340.         title: "Which languages are commonly used for styling or structuring web pages?",
341.         choices: [
342.           { id: "q2-css", label: "CSS", detail: "Used to style layouts, typography, color, and motion." },
343.           { id: "q2-html", label: "HTML", detail: "Used to define the structure and meaning of page content." },
344.           { id: "q2-go", label: "Go", detail: "A compiled language often used for servers and tooling." },
