357.         ],
358.         correctAnswers: ["SQL", "R"]
359.       }
360.     ];
361. 
362.     const arraysMatch = (left, right) =>
363.       left.length === right.length && left.every((value, index) => value === right[index]);
364. 
365.     function CheckboxOption(choice, questionId) {
366.       const label = document.createElement("label");
367.       label.className = "choice";
368. 
369.       const input = document.createElement("input");
370.       input.type = "checkbox";
371.       input.name = questionId;
372.       input.value = choice.label;
373.       input.id = choice.id;
374. 
375.       const text = document.createElement("span");
376.       text.className = "choice__text";
377. 
378.       const title = document.createElement("span");
379.       title.className = "choice__label";
380.       title.textContent = choice.label;
381. 
382.       const detail = document.createElement("span");
383.       detail.className = "choice__detail";
384.       detail.textContent = choice.detail;
385. 
386.       text.append(title, detail);
387.       label.append(input, text);
388.       return label;
389.     }
390. 
391.     function QuizQuestion(question) {
392.       const wrapper = document.createElement("div");
393.       wrapper.className = "form-field";
394. 
395.       const fieldset = document.createElement("fieldset");
396.       if (question.helpText) {
397.         fieldset.setAttribute("aria-describedby", question.id + "-help");
398.       }
399. 
400.       const legend = document.createElement("legend");
401.       legend.textContent = question.title;
402.       fieldset.appendChild(legend);
403. 
404.       if (question.helpText) {
405.         const help = document.createElement("p");
406.         help.className = "help-text";
407.         help.id = question.id + "-help";
408.         help.textContent = question.helpText;
409.         fieldset.appendChild(help);
410.       }
411. 
412.       const choices = document.createElement("div");
413.       choices.className = "choices";
414.       question.choices.forEach((choice) => {
415.         choices.appendChild(CheckboxOption(choice, question.id));
416.       });
417. 
418.       fieldset.appendChild(choices);
419.       wrapper.appendChild(fieldset);
420.       return wrapper;
421.     }
422. 
423.     function App() {
424.       const shell = document.createElement("div");
425.       shell.className = "page-shell";
426. 
427.       const hero = document.createElement("header");
428.       hero.className = "hero";
429.       hero.innerHTML = `
430.         <span class="eyebrow">Language Lab</span>
431.         <h1>Test your computer language instincts</h1>
432.         <p>A short multi-select quiz with a polished, product-style layout. Each question can have more than one correct answer.</p>
433.       `;
434. 
435.       const card = document.createElement("section");
436.       card.className = "quiz-card";
437.       card.setAttribute("aria-labelledby", "quiz-title");
438. 
439.       const cardHeader = document.createElement("div");
440.       cardHeader.className = "quiz-card__header";
441.       cardHeader.innerHTML = `
442.         <h2 id="quiz-title">3-question quiz</h2>
443.         <div class="quiz-meta">
444.           <span>4 answer choices per question</span>
445.           <span>Select multiple answers where appropriate</span>
446.         </div>
447.       `;
448. 
449.       const cardBody = document.createElement("div");
450.       cardBody.className = "quiz-card__body";
451. 
452.       const form = document.createElement("form");
453.       form.noValidate = true;
454.       form.setAttribute("aria-describedby", "result-status");
455. 
456.       quizQuestions.forEach((question) => {
457.         form.appendChild(QuizQuestion(question));
458.       });
459. 
460.       const footer = document.createElement("div");
461.       footer.className = "quiz-card__footer";
462. 
463.       const actions = document.createElement("div");
464.       actions.className = "actions";
465. 
466.       const button = document.createElement("button");
467.       button.type = "submit";
468.       button.className = "button";
469.       button.textContent = "Submit quiz";
470. 
471.       const result = document.createElement("div");
472.       result.className = "result";
473.       result.id = "result-status";
474.       result.setAttribute("aria-live", "polite");
475. 
476.       const panel = document.createElement("div");
477.       panel.className = "result-panel";
478.       panel.hidden = true;
479. 
480.       actions.append(button, result);
481.       footer.append(actions, panel);
482. 
483.       form.addEventListener("submit", (event) => {
484.         event.preventDefault();
485. 
486.         let score = 0;
487.         const summaryItems = [];
488. 
489.         quizQuestions.forEach((question) => {
490.           const selected = Array.from(form.querySelectorAll(`input[name="${question.id}"]:checked`))
491.             .map((input) => input.value)
492.             .sort();
493.           const correct = [...question.correctAnswers].sort();
494. 
495.           if (arraysMatch(selected, correct)) {
496.             score += 1;
497.           }
498. 
499.           summaryItems.push(
500.             `<li><strong>${question.title}</strong> &mdash; You chose ${selected.length ? selected.join(", ") : "nothing"}.</li>`
501.           );
502.         });
503. 
504.         result.textContent = `You scored ${score} out of ${quizQuestions.length}.`;
505.         panel.hidden = false;
506.         panel.innerHTML = `
507.           <h3>Quiz summary</h3>
508.           <p>Your selections have been recorded.</p>
509.           <ul>${summaryItems.join("")}</ul>
510.         `;
511.       });
512. 
513.       form.appendChild(footer);
514.       cardBody.appendChild(form);
515.       card.append(cardHeader, cardBody);
516.       shell.append(hero, card);
517.       return shell;
518.     }
519. 
520.     document.getElementById("app").appendChild(App());
521.   </script>
